// adder_scoreboard.sv
// Reference model computes expected output and checks against actual DUT output
class adder_scoreboard extends uvm_scoreboard;
  `uvm_component_utils(adder_scoreboard)

  uvm_analysis_imp #(adder_seq_item, adder_scoreboard) analysis_export;

  int unsigned pass_count;
  int unsigned fail_count;

  function new(string name = "adder_scoreboard", uvm_component parent = null);
    super.new(name, parent);
    pass_count = 0;
    fail_count = 0;
  endfunction

  virtual function void build_phase(uvm_phase phase);
    super.build_phase(phase);
    analysis_export = new("analysis_export", this);
  endfunction

  // Reference model and checker
  virtual function void write(adder_seq_item item);
    logic [4:0] expected_result;
    logic [3:0] exp_sum;
    logic       exp_cout;

    // Reference model: simple addition
    expected_result = 5'(item.a) + 5'(item.b) + 5'(item.cin);
    exp_sum  = expected_result[3:0];
    exp_cout = expected_result[4];

    if (item.sum !== exp_sum || item.cout !== exp_cout) begin
      `uvm_error(get_type_name(), $sformatf(
        "MISMATCH: a=%0d b=%0d cin=%0b | got sum=%0d cout=%0b | exp sum=%0d cout=%0b",
        item.a, item.b, item.cin, item.sum, item.cout, exp_sum, exp_cout))
      fail_count++;
    end else begin
      `uvm_info(get_type_name(), $sformatf(
        "PASS: a=%0d b=%0d cin=%0b => sum=%0d cout=%0b",
        item.a, item.b, item.cin, item.sum, item.cout), UVM_HIGH)
      pass_count++;
    end

    // Additional checks complementing SVA
    // Check carry-out correctness
    if ((5'(item.a) + 5'(item.b) + 5'(item.cin)) > 5'd15) begin
      if (item.cout !== 1'b1)
        `uvm_error(get_type_name(), $sformatf(
          "COUT should be 1 for a=%0d b=%0d cin=%0b", item.a, item.b, item.cin))
    end else begin
      if (item.cout !== 1'b0)
        `uvm_error(get_type_name(), $sformatf(
          "COUT should be 0 for a=%0d b=%0d cin=%0b", item.a, item.b, item.cin))
    end

    // Check no X/Z
    if ($isunknown(item.sum) || $isunknown(item.cout))
      `uvm_error(get_type_name(), "X/Z detected on outputs")

  endfunction

