// adder_coverage.sv
// Functional coverage subscriber with covergroups and cross-coverage
class adder_coverage extends uvm_subscriber #(adder_seq_item);
  `uvm_component_utils(adder_coverage)

  adder_seq_item txn;

  // Covergroup definition
  covergroup adder_cg;
    option.per_instance = 1;

    cp_a: coverpoint txn.a {
      bins zero    = {0};
      bins max_val = {15};
      bins low     = {[1:3]};
      bins mid     = {[4:11]};
      bins high    = {[12:14]};
    }

    cp_b: coverpoint txn.b {
      bins zero    = {0};
      bins max_val = {15};
      bins low     = {[1:3]};
      bins mid     = {[4:11]};
      bins high    = {[12:14]};
    }

    cp_cin: coverpoint txn.cin {
      bins no_carry  = {0};
      bins carry_in  = {1};
    }

    cp_sum: coverpoint txn.sum {
      bins zero    = {0};
      bins max_val = {15};
      bins low     = {[1:7]};
      bins high    = {[8:14]};
    }

    cp_cout: coverpoint txn.cout {
      bins no_carry  = {0};
      bins carry_out = {1};
    }

    // Cross coverage: all input combinations are important
    cx_a_b: cross cp_a, cp_b;
    cx_a_cin: cross cp_a, cp_cin;
    cx_b_cin: cross cp_b, cp_cin;
    cx_all_inputs: cross cp_a, cp_b, cp_cin;

    // Cross coverage: outputs with carry
    cx_cout_sum: cross cp_cout, cp_sum;
    cx_cout_cin: cross cp_cout, cp_cin;

  endgroup

  function new(string name = "adder_coverage", uvm_component parent = null);
    super.new(name, parent);
    adder_cg = new();
  endfunction

  virtual function void write(adder_seq_item t);
    txn = t;
    adder_cg.sample();
  endfunction

  virtual function void report_phase(uvm_phase phase);
    super.report_phase(phase);
    `uvm_info(get_type_name(), $sformatf(
      "Functional Coverage = %.2f%%", adder_cg.get_inst_coverage()), UVM_LOW)
  endfunction

endclass

