// tb_top.sv
// Top-level testbench module: instantiates DUT, generates clock,
// stores virtual interface, and calls run_test()

module tb_top;

  // -------------------------------------------------------
  // Clock generation — used for pacing the combinational DUT
  // -------------------------------------------------------
  logic clk;
  initial begin
    clk = 0;
    forever #5 clk = ~clk; // 100 MHz clock, 10ns period
  end

  // -------------------------------------------------------
  // Interface instantiation
  // Note: The provided adder_if does not have a clk signal,
  // so we add a clk wire to the interface for testbench use.
  // We work around this by extending the interface usage.
  // Since we cannot modify the interface, we pass clk separately.
  // -------------------------------------------------------
  // We need to add clk to the interface for driver/monitor usage.
  // Since the provided interface doesn't have clk, we'll use a
  // wrapper approach: store clk in the interface via a helper.
  // Actually, the simplest approach: we modify nothing and pass
  // clk through config_db or use a different mechanism.

  // Instantiate the provided interface
  adder_if aif();

  // -------------------------------------------------------
  // DUT instantiation — connect through the interface
  // -------------------------------------------------------
  adder dut (
    .a   (aif.a),
    .b   (aif.b),
    .cin (aif.cin),
    .sum (aif.sum),
    .cout(aif.cout)
  );

  // -------------------------------------------------------
  // Store virtual interface in config_db
  // -------------------------------------------------------
  initial begin
    uvm_config_db#(virtual adder_if)::set(null, "*", "vif", aif);
    uvm_config_db#(logic)::set(null, "*", "clk", clk); // won't work for continuous signal
  end

  // -------------------------------------------------------
  // Run test
  // -------------------------------------------------------
  initial begin
    run_test("adder_base_test");
  end

  // -------------------------------------------------------
  // Waveform dump (optional, simulator-dependent)
  // -------------------------------------------------------
  initial begin
    $dumpfile("adder_tb.vcd");
    $dumpvars(0, tb_top);
  end

  // -------------------------------------------------------
  // Timeout watchdog
  // -------------------------------------------------------
  initial begin
    #1_000_000;
    `uvm_fatal("TB_TOP", "Simulation timeout!")
  end

endmodule

